(0, FALSE, TRUE, 256, TIMESTAMP '2024-10-25 12:05:42', 41, 1, 1, TIMESTAMP '2024-08-15 12:05:42', 0, U&'\c544\bb34\d2bc \c2dc\b9ac\c988 28\ad8c. \c815\d61c\c724 \c5d0\c138\c774. \ba54\baa8\b294 \c0b6\c744 \c704\d55c \c7ac\b8cc\c774\c790 \c608\c5f4 \acfc\c815\c774\b77c\ace0 \bbff\b294 \d55c \ba54\baa8\c8fc\c758\c790\c758 \ae30\b85d\c73c\b85c, \be44\ba54\baa8\c8fc\c758\c790\ac00 \ba54\baa8\c8fc\c758\c790\ac00 \b418\ace0, \afc8\c774 \d604\c2e4\b85c \bd80\d654\d558\ace0, \c4f4 \b300\b85c \c0b4 \ac8c \b41c \c774\c57c\ae30\c774\b2e4. \adf8\b9ac\ace0 \bb34\c5c7\bcf4\b2e4 \ba54\baa8\c7a5 \c548\c5d0\c11c \b354 \c6a9\ac10\d574\c9c4 \c774\c57c\ae30\c774\b2e4.', U&'\c544\bb34\d2bc, \ba54\baa8 - \c774\ac83\c73c\b85c \b098\c758 \b0b4\c77c\c774 \b9cc\b4e4\c5b4\c9c8 \ac83\c774\b2e4'),
(0, FALSE, TRUE, 259, TIMESTAMP '2024-10-26 12:05:42', 42, 1, 1, TIMESTAMP '2024-08-21 12:05:42', 0, U&'\c0ac\b78c\c5d0 \b530\b77c \b3c5\c11c\c758 \baa9\c801\c774 \b2e4\b978 \b9cc\d07c \b3c5\c11c\bc95 \c5ed\c2dc \b2ec\b77c\c57c \d55c\b2e4. \c774 \cc45\c740 \b2e8\c21c\d788 \c624\b798 \ae30\c5b5\d558\ae30 \c704\d55c \b3c5\c11c\b97c \b118\c5b4 \c0b6\c744 \bc14\afb8\b294 \b3c5\c11c\bc95\c774\b2e4. \cc45\c758 \b0b4\c6a9\c744 \c880 \b354 \c624\b798 \ae30\c5b5\d558\ace0 \c2f6\c740 \c0ac\b78c\b4e4\c5d0\ac8c, \b610 \b3c5\c11c\b97c \d1b5\d574 \c0b6\c758 \bcc0\d654\b97c \baa8\c0c9\d558\ace0\c790 \d558\b294 \c0ac\b78c\b4e4\c5d0\ac8c \2018\ba54\baa8 \b3c5\c11c\bc95\2019\c740 \cd5c\c801\c758 \b3c5\c11c\bc95\c774\b2e4.', U&'\b2e8 \d55c \ad8c\c744 \c77d\c5b4\b3c4 \c81c\b300\b85c \b0a8\b294 \ba54\baa8 \b3c5\c11c\bc95'),
(0, FALSE, TRUE, 282, TIMESTAMP '2024-10-27 12:05:42', 43, 1, 1, TIMESTAMP '2024-08-27 12:05:42', 0, U&'\b514\c9c0\d138 \c2dc\b300, \c65c \b2e4\c2dc \c544\b0a0\b85c\adf8 \ba54\baa8\c778\ac00? \b2e8\c21c\d788 \c790\b8cc\b098 \c815\bcf4 \c218\c9d1\c744 \c704\d55c \ba54\baa8\b97c \b118\c5b4 \b17c\b9ac\c801 \c0ac\ace0\b97c \d0a4\c6b0\ace0 \c544\c774\b514\c5b4\b97c \bc1c\acac\d558\ba70 \c0dd\c0b0\c131\c744 \b192\c774\b294 \b3c4\ad6c\b85c\c11c \c544\b0a0\b85c\adf8 \ba54\baa8\c758 \c911\c694\c131\c744 \c790\c138\d788 \c124\ba85\d55c\b2e4.', U&'\ba54\baa8\c758 \c7ac\bc1c\acac - \c5b4\c81c\c758 \b098\b97c \bcc0\d654\c2dc\d0a4\b294 \c791\c9c0\b9cc \ac15\b825\d55c \ba54\baa8\c758 \d798'),
(0, FALSE, TRUE, 284, TIMESTAMP '2024-10-28 12:05:42', 44, 1, 1, TIMESTAMP '2024-09-30 12:05:42', 0, U&'\ac10\c0ac\d569\b2c8\b2e4 \d55c\b9c8\b514 \b9d0\c744 \d558\ae30 \c2dc\c791\d558\b2c8 \c88b\c740 \c77c\c774 \c0dd\ae30\ae30 \c2dc\c791\d588\b2e4. \ac10\c0ac\ba54\baa8\b97c \c804\d558\ae30 \c2dc\c791\d558\b2c8 \c88b\c740 \c0ac\b78c\b4e4\c774 \b098\d0c0\b098\ae30 \c2dc\c791\d588\b2e4. \ac10\c0ac\ba54\baa8\b97c \b9c8\c74c\c885\c774\c5d0 \c801\c5b4 \c8fc\bcc0\c5d0 \d37c\b728\b9ac\c790. \b098\b97c \b354 \d070 \b098\b85c \c131\c7a5\c2dc\cf1c \c904 \ac10\c0ac\c758 \b9d0 \bc95\ce59. \c644\c804\d55c \d589\bcf5\c73c\b85c \ac00\b294 \b2e8 \d558\b098\c758 \ae38 \ac10\c0ac\ba54\baa8.', U&'\ae30\c801\c744 \b9cc\b4dc\b294 \ac10\c0ac\ba54\baa8 - \c624\b298 \b2f9\c2e0\c758 \c784\bb34'),
(0, FALSE, TRUE, 289, TIMESTAMP '2024-10-29 12:05:42', 45, 1, 1, TIMESTAMP '2024-10-04 12:05:42', 0, U&'\c720\c6a9\d55c \ba54\baa8 \bc29\bc95\c744 \c18c\ac1c\d55c \bca0\c2a4\d2b8\c140\b7ec \ba54\baa8\c758 \ae30\c220\c758 \c800\c790 \c0ac\ce74\d1a0 \cf04\c9c0\c758 2009\b144 \c2e0\c791. \c0ac\ce74\d1a0 \cf04\c9c0\b294 \c774 \cc45\c744 \d1b5\d574 \ae30\c874\c758 \ba54\baa8 \d65c\c6a9\bc95\c744 \c81c\c548\d558\b294 \b3d9\c2dc\c5d0 \c9c1\ac10\acfc \ae30\bc1c\d568\c744 \b2f4\b2f9\d558\b294 \c6b0\b1cc, \b17c\b9ac\c801 \c0ac\ace0\c640 \bd84\c11d \b2a5\b825\c774 \b6f0\c5b4\b09c \c88c\b1cc, \adf8\b9ac\ace0 \b450 \ac00\c9c0 \d65c\b3d9\c744 \baa8\b450 \d65c\c6a9\d55c \c0c8\b85c\c6b4 \ba54\baa8 \be44\bc95\c744 \acf5\ac1c\d55c\b2e4.', U&'\b1cc\b97c \c6c0\c9c1\c774\b294 \ba54\baa8 - \c190\c774 \b1cc\b97c \c6c0\c9c1\c778\b2e4!!');    
